#define main ReadOnlyPoleUnusedMain
#include "diagnose_scri_pole.cpp"
#undef main
#include <memory>
#include "mesh/cubed_sphere/anchored_radial_scri_probe.hpp"
#include "z4c/hyperboloidal/reference_gauge.hpp"
Real RhsSize(const h::Z4cRHS<Real>&r){Real v=std::max({std::abs(r.chi),std::abs(r.trace),std::abs(r.theta)});for(int i=0;i<3;++i){v=std::max(v,std::abs(r.lambda[i]));for(int j=0;j<3;++j)v=std::max({v,std::abs(r.metric[i][j]),std::abs(r.a[i][j])});}return v;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=3)throw std::runtime_error("checkpoint tag");auto snap=cubed_sphere::CompositeCheckpoint::Read(argv[1],argv[2]);cubed_sphere::CompositeDifference g(snap.mesh,4,snap.radial_interface_stencils);if(g.active.size()>50000)throw std::runtime_error("bounded50000");cubed_sphere::ScriSurface surface(g,22,7);V volume(22*g.count,0),boundary(surface.values.size(),0);h::CMCReference<Real> reference{1,1};Real maxconstant=0,maxpole=0,maxlimit=0,maxclock=0;
 for(int method=0;method<4;++method){cubed_sphere::HermiteBoundaryProbe probe(surface,volume,boundary,22);std::unique_ptr<cubed_sphere::RadialScriJetProbe> plan;if(method==3)plan=std::make_unique<cubed_sphere::AnchoredRadialScriProbe>(surface,13,cubed_sphere::RadialScriJetProbe::Basis::LogRadius,6);else plan=std::make_unique<cubed_sphere::RadialScriJetProbe>(surface,method==2?9:7,method?cubed_sphere::RadialScriJetProbe::Basis::LogRadius:cubed_sphere::RadialScriJetProbe::Basis::Radius);plan->Apply(probe);for(const auto&row:surface.rows){const auto&x=row.geometry.x;Real q[3]={1,(row.j+.5)/g.n,(row.k+.5)/g.n};const auto sample=probe.At(row.block,q);for(int f=0;f<22;++f){maxconstant=std::max(maxconstant,std::abs(sample.value[f]));for(int i=0;i<3;++i){maxconstant=std::max(maxconstant,std::abs(sample.d[f][i]));for(int j=0;j<3;++j)maxconstant=std::max(maxconstant,std::abs(sample.dd[f][i][j]));}}const auto u=h::UnpackComposite(x,sample.value,sample.d,sample.dd,true,0,2);const auto o=Omega(x,u);const auto parts=h::ConformalRHS(u,o,Real(4),Real(-.99),true);const auto normal=h::TensorPoleNormalJet(u,o,x,x,Real(4),Real(-.99),Real(1),Real(1),true,true);const auto rate=h::TensorScriLimit(parts.regular,normal,Real(-1));const auto gauge=h::UnfactoredReferenceGauge(reference,reference.At(x[0],x[1],x[2]),u,h::GaugeParameters<Real>{1,0,2,0},true,true);if(!parts.valid||!gauge.valid)throw std::runtime_error("invalid Minkowski source");maxpole=std::max(maxpole,RhsSize(parts.pole));maxlimit=std::max(maxlimit,RhsSize(rate));maxclock=std::max(maxclock,std::abs(gauge.regular.alpha-normal.lapse.derivative));}}
 std::cout<<std::setprecision(17)<<"{\"methods\":4,\"rows_each\":"<<surface.rows.size()<<",\"constant_stored_jet_max\":"<<maxconstant<<",\"tensor_pole_max\":"<<maxpole<<",\"tensor_limit_max\":"<<maxlimit<<",\"clock_rate_max\":"<<maxclock<<",\"no_evolution\":true}\n";if(maxconstant||maxpole>1e-12||maxlimit>1e-12||maxclock>1e-12)throw std::runtime_error("radial Minkowski source control failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
